import json
from pathlib import Path
D={k:[] for k in ['typography','color','layout','clients','toolkit','visual','judgment']}
def add(lab,title,focus,visual,client,designer,follow,target,a2,b2,chunks,question,choices,answer,reasons,repair_options,repair_answer,repair_why,client_role,designer_role,mission,success):
 D[lab].append(dict(id=f'{lab}-{len(D[lab])+1}',title=title,focus=focus,visual=visual,dialogue=[['Client',client],['Designer',designer],['Client',follow]],target=target,levels={'A2':{'model':a2,'hint':'Say one clear sentence. Then add a reason or a question.'},'B1':{'model':target,'hint':'Connect your design choice to the client’s goal.'},'B2':{'model':b2,'hint':'Explain a tradeoff, then invite a decision.'}},chunks=chunks,meaning={'question':question,'choices':choices,'answer':answer,'reasons':reasons},repair={'question':'Which sentence would you use in this exchange?','choices':repair_options,'answer':repair_answer,'reason':repair_why},roles={'client':client_role,'designer':designer_role},mission=mission,success=success))
add('typography','Compare two headlines','Comparatives: larger than; easier to read','type-size','I need people to notice the opening offer. Which headline works better?','The headline in B is larger than the headline in A. It is easier to read from a distance.','Good. Please keep the smaller details below it.','The headline in B is larger than the headline in A.','The headline in B is bigger.','Although B uses more space, its larger headline makes the offer easier to notice.',[['larger than','Compare the sizes of two things.','The headline in B is larger than the headline in A.'],['easier to read','Describe how much effort reading takes.','The larger letters are easier to read from the back of the room.'],['from a distance','When the viewer is far away.','Can you read the offer from a distance?']],'Why does the designer prefer B?',['The main headline is larger.','B has more opening information.','A has a spelling error.'],0,['Yes. The headline is larger; the words are the same.','The information is unchanged. Compare the size of the headline.','Both versions use the same spelling. Look at the size.'],['B is more larger than A.','B is larger than A.','B is larger that A.'],1,'Use “larger than”. Do not add “more” to this -er comparative.','You want an opening offer visible from the back of a classroom. The brand name can be smaller. Do not tell the designer your priority until they ask.','You have two versions with the same words. Ask which message must stand out, compare the sizes, and recommend one.','Agree on one headline hierarchy for the opening poster.',['Ask what should stand out first.','Use a comparison with than.','Connect the size to where viewers will see it.'])
add('typography','Explain a font choice','Purpose: to + verb; impressions: looks / feels','type-style','Our café should feel calm and welcoming.','I chose a serif headline to give the poster a quieter feel. I kept the body text simple so the details are easy to read.','Can you show me a second option before we decide?','I chose a serif headline to give the poster a quieter feel.','This font looks calm. I chose it for the café.','I would keep the serif headline for a quieter feel, while using a simple sans-serif font for the practical details.',[['I chose','Name a decision you already made.','I chose a serif headline.'],['to give','Explain the purpose of the choice.','I chose this font to give the poster a quieter feel.'],['a quieter feel','An impression, not a guaranteed reaction.','To me, the serif version has a quieter feel.']],'What is the purpose of the serif headline?',['To make the opening date disappear.','To suggest a calmer tone.','To prove every café must use serif type.'],1,['The details still need to be clear. The choice is about tone.','Yes. The designer connects the font to the client’s requested tone.','This is a recommendation for this café, not a rule for all cafés.'],['I chose this font to make the poster feel calmer.','I chose this font for make the poster calmer.','I chose this font to making the poster calmer.'],0,'After “to” for purpose, use the base verb: to make.','Your café is quiet during the day but hosts lively evening events. Ask whether one font choice can work for both.','Suggest a calm daytime version and an energetic evening alternative. Explain an impression with “looks”, “feels”, or “may”.','Recommend a type direction without pretending the feeling is universal.',['Name a visible choice.','Explain its purpose with to + verb.','Ask whether the tone matches the intended event.'])
add('typography','Translate vague feedback','Clarifying questions; either / or','type-size','Could you make it pop?','Which element should stand out first: the café name or the opening offer?','The offer. People already know our name.','Which element should stand out first: the café name or the opening offer?','Should the name or the offer be bigger?','When you say “make it pop”, are you looking for stronger emphasis on the offer or a more energetic overall style?', [['stand out','Be easier to notice than nearby elements.','The offer should stand out.'],['Which element','Ask the client to identify a particular part.','Which element should stand out first?'],['when you say','Check what the client means by a phrase.','When you say “bold”, do you mean the font weight or the mood?']],'What did “make it pop” mean for this client?',['Add as many colors as possible.','Change every font.','Give the offer more emphasis.'],2,['The client identifies the offer, not a color change.','The designer asks before changing the fonts.','Yes. The clarification gives the designer a specific next step.'],['What you mean by “pop”?','What do you mean by “pop”?','What does you mean by “pop”?'],1,'Use “do” with “you” in this present-simple question.','You want more emphasis on the 50% opening offer, not a different brand personality. Begin with “make it pop”.','Do not redesign immediately. Ask a specific either/or question, then confirm one change.','Turn vague feedback into one agreed revision.',['Ask a clarifying question.','Restate the client’s priority.','Confirm one visible change.'])
add('color','Describe a readable change','Before / now; comparative + reason','contrast','The gold text looks lovely. Why did you change it?','The forest text is easier to read on the cream background. We can keep gold for the decorative line.','That works. Please keep the warm feeling.','The forest text is easier to read on the cream background.','The green text is easier to read.','The gold can remain as an accent, while the forest text provides stronger contrast for the essential details.',[['on the background','Locate text against the surface behind it.','The text is hard to read on this background.'],['easier to read','Compare readability rather than beauty alone.','The forest text is easier to read.'],['keep as an accent','Retain a color for a smaller decorative role.','We can keep gold as an accent.']],'What will happen to the gold?',['It will be removed everywhere.','It can stay in a decorative line.','It must become the body text.'],1,['The designer offers to keep gold for decoration.','Yes. The function changes; the palette can stay warm.','The important text is changing to forest for readability.'],['The text is more easy to read.','The text is easier to read.','The text is easier read.'],1,'Use the comparative “easier”, followed by “to read”.','You like gold because it matches your café décor. The opening date must still be readable on a phone.','Keep the warm brand impression while recommending a readable text/background pair.','Explain a color revision without dismissing the client’s preference.',['Acknowledge what the client likes.','Compare the readable versions.','Suggest a role for the original color.'])
add('color','Ask about a palette','Open questions; preferences; audience','palette','Can you choose the colors for us?','What feeling would you like customers to have: calm, energetic, or formal?','Calm. Our audience is students who come to read and talk.','What feeling would you like customers to have?','Should the colors feel calm or lively?','Before choosing a palette, could you tell me what impression you want to create and who the main audience is?', [['would you like','Ask about a preference politely.','What feeling would you like the colors to create?'],['main audience','The people the design is mainly for.','Who is the main audience?'],['muted palette','A group of less intense colors.','A muted palette may fit the quieter brief.']],'Which information guides the palette choice?',['The audience and desired feeling.','The designer’s favorite color alone.','The largest available number of colors.'],0,['Yes. The designer learns the purpose before choosing.','A personal preference is not enough to understand this brief.','More colors do not automatically fit the audience.'],['What feeling would you like to create?','What feeling you would like to create?','What feeling would you likes to create?'],0,'In a direct question, put “would” before “you”; use the base verb “like”.','Your daytime customers want a quiet place to study. You dislike neon colors. Reveal these details only when asked.','Ask about the audience and feeling. Compare the muted and vibrant sample palettes.','Choose a palette based on a short discovery conversation.',['Ask an open question.','Name the audience.','Recommend a palette with a reason.'])
add('color','Give a conditional option','If + present, can + verb','palette','We might use the poster on a bright outdoor sign too.','If people see it from the street, we can use stronger contrast and fewer small details.','Let’s make a separate version for the sign.','If people see it from the street, we can use stronger contrast.','For the street sign, we need clear colors.','If the design needs to work outdoors, I would create a separate version with stronger contrast and fewer details.', [['if people see it','Introduce a viewing condition.','If people see it from the street, the offer needs to be clear.'],['we can use','Offer an available option.','We can use stronger contrast.'],['a separate version','A second design adapted to another use.','The sign needs a separate version.']],'Why does the designer suggest a second version?',['To use a random new brand.','To match a different viewing situation.','To hide the same opening details.'],1,['The brand can stay consistent. The use is different.','Yes. A street sign needs different readability decisions.','The aim is clearer information, not hiding it.'],['If people will see it from the street, we can simplify it.','If people see it from the street, we can simplify it.','If people seeing it from the street, we can simplify it.'],1,'For this real possible condition, use present simple after “if”: if people see it.','You need both a phone post and a street sign. The sign will be read quickly from a distance.','Ask where each version will be seen. Offer a conditional recommendation and define two deliverables.','Adapt the same palette to two viewing conditions.',['Ask about the viewing conditions.','Use an if-clause naturally.','Confirm whether a second version is in scope.'])
add('layout','Describe where things are','Position phrases: above / below / next to','layout','Where have you put the opening details?','The date is below the headline, and the location is next to it. They are grouped together.','Good. That makes the information easy to find.','The date is below the headline, and the location is next to it.','The date is below the headline.','I grouped the date and location below the headline so the practical details form one clear unit.', [['below the headline','Lower than the main line of text.','The date is below the headline.'],['next to it','Beside the detail just mentioned.','The location is next to the date.'],['grouped together','Put related items close to one another.','The practical details are grouped together.']],'Which details are grouped together?',['The date and location.','Only the headline letters.','Every element in a random corner.'],0,['Yes. They tell the viewer when and where to come.','The question is about practical details, not letter spacing.','Grouping is intentional; these details belong together.'],['The date is under to the headline.','The date is below the headline.','The date is below of the headline.'],1,'Use “below” directly before the noun phrase: below the headline.','You want customers to find the date and location together. Ask the designer to point out where they are.','Describe two positions clearly. Avoid “it” until you have named the detail.','Guide a client around a layout with unambiguous English.',['Name each element before referring to it.','Use two accurate position phrases.','Explain why the details are together.'])
add('layout','Explain a revision','Past-simple change + purpose','layout','What did you change in the second version?','I moved the details below the headline to make the layout easier to scan.','Please keep this version and make the address a little larger.','I moved the details below the headline to make the layout easier to scan.','I moved the details. Now the layout is clearer.','I reorganised the practical details into one group, which makes the layout easier to scan without adding more content.', [['I moved','Describe a completed change.','I moved the opening date.'],['to make','Give the purpose of a change.','I moved the date to make it easier to find.'],['scan the layout','Look quickly for useful information.','Customers can scan the layout quickly.']],'What changed between the versions?',['All the opening facts.','The arrangement of the same information.','The location of the café.'],1,['The poster still carries the same facts.','Yes. The revision changes the arrangement rather than the facts.','The café has not moved; its details moved on the poster.'],['I moved the date to make it easier to find.','I moved the date for make it easier to find.','I move the date yesterday to make it easier to find.'],0,'Use past simple for the completed change and “to make” for its purpose.','Your address has been overlooked in earlier posters. You need it clearer, but the opening offer should still lead.','Describe a completed revision, then ask which detail needs the next change.','Present a revision and respond to one further request.',['Describe a specific completed change.','Explain its purpose.','Confirm the next request.'])
add('layout','Push back on clutter','Too much / too many; polite recommendation','clutter','Can we add every menu item and three photos?','There is too much information for a small phone post. I suggest a short invitation and a link to the full menu.','All right. Keep the opening offer and the address.','There is too much information for a small phone post.','There is too much text. Let’s keep the offer.','Although the menu matters, adding every item would compete with the opening offer; I suggest linking to the full menu instead.', [['too much information','Information is uncountable in this use.','There is too much information.'],['too many elements','Elements are separate countable things.','There are too many competing elements.'],['I suggest','Offer a recommendation respectfully.','I suggest keeping the opening offer.']],'What is the alternative to adding the full menu?',['Delete the opening offer.','Make every line smaller.','Use a short invitation and a menu link.'],2,['The opening offer is the message that should lead.','Smaller text may make the problem worse.','Yes. This keeps the post focused without losing access to the menu.'],['There are too many informations.','There is too much information.','There is too many information.'],1,'“Information” is uncountable: too much information.','You believe including the whole menu will attract customers. Your real priority is getting opening-day visitors.','Acknowledge the menu request, explain the size constraint, and offer a way to keep the full menu accessible.','Negotiate a focused phone layout.',['Acknowledge the client’s goal.','Use too much or too many accurately.','Offer a practical alternative.'])
add('clients','Clarify a vague request','Could you clarify / do you mean','client-brief','Can you make the design more professional?','Could you clarify what you mean by professional? Do you mean simpler colors, a cleaner layout, or a more formal typeface?','A cleaner layout, please. The information feels crowded.','Could you clarify what you mean by professional?','Do you mean a cleaner layout?','Could you point to a reference that captures the style you mean, so I can make the next revision more focused?', [['could you clarify','Ask someone to make an unclear point specific.','Could you clarify what you mean?'],['do you mean','Check one possible interpretation.','Do you mean a cleaner layout?'],['a reference','An example to compare or discuss.','Could you share a reference?']],'Which action would best follow the clarification?',['Change the layout spacing and grouping.','Change every design feature at once.','Ignore the request because it is vague.'],0,['Yes. The client has identified the crowded layout.','The clarification narrows the revision to a cleaner layout.','The designer can use a question to make the request useful.'],['Could you clarify what do you mean?','Could you clarify what you mean?','Could you clarifying what you mean?'],1,'Inside “Could you clarify…”, use statement order: what you mean.','You are worried that your opening poster looks crowded. Begin with “make it professional”; explain the crowding when asked.','Ask for clarification and propose one focused revision, not a complete unexplained redesign.','Turn a vague brief into a usable next step.',['Ask without sounding dismissive.','Offer interpretations or ask for a reference.','Confirm the specific change.'])
add('clients','Define an extra revision','Included scope; can + fee + time','client-scope','We thought revisions were included.','Two rounds were included, and both are complete. I can make this additional revision for an extra fee.','Please send me the fee before you begin.','I can make this additional revision for an extra fee.','I can do one more change for an extra fee.','The two included rounds are complete; I can quote for an additional revision and confirm the delivery date before proceeding.', [['were included','Describe what the agreement covered.','Two revision rounds were included.'],['additional revision','A change beyond the agreed number of rounds.','This is an additional revision.'],['before I begin','Make the sequence clear.','I will confirm the fee before I begin.']],'What does the client ask the designer to do next?',['Begin immediately without agreement.','Send the extra fee first.','Pretend the extra round was already included.'],1,['The client wants the fee before work starts.','Yes. Confirm the cost before beginning the additional work.','The included rounds have already been used.'],['I can to make an extra revision.','I can making an extra revision.','I can make an extra revision.'],2,'After “can”, use the base verb without “to”: can make.','You used both included rounds. You now want a second-language version, but you have not budgeted for it.','Calmly name the original agreement. Clarify whether this is a new deliverable and offer a priced option.','Agree what happens after included revisions are used.',['Refer to the agreement without blaming.','Name the extra work.','Confirm fee and timing before starting.'])
add('clients','Recover after a late update','Apology + status + future commitment','client-update','I haven’t heard from you. Is the draft still coming today?','I’m sorry I missed the update. The first draft is ready, but I still need to check the address. I’ll send it by 6 pm Bangladesh time.','Thanks. Please message me if that timing changes.','I will send the checked draft by 6 pm Bangladesh time.','I’m sorry. I will send the draft by 6 pm.','I missed the agreed update, and I’m sorry; the draft is ready for a final copy check, and I will send it by 6 pm Bangladesh time.', [['missed the update','Did not communicate at the agreed time.','I missed the update this morning.'],['still need to','Name unfinished work honestly.','I still need to check the address.'],['by 6 pm','No later than 6 pm, rather than exactly at 6 pm.','I will send it by 6 pm Bangladesh time.']],'What still needs to happen before delivery?',['The address needs a final check.','The designer must invent a new opening date.','Nothing; the draft has already been delivered.'],0,['Yes. The designer gives a specific unfinished step.','The approved information should not be invented.','Ready for checking does not mean already delivered.'],['I will sent it by 6 pm.','I will send it by 6 pm.','I will sending it by 6 pm.'],1,'After “will”, use the base verb: will send.','Your team needs the draft before a meeting. You are in another time zone. Ask exactly when it will arrive.','Give an honest status, a specific deadline with time zone, and an update plan if there is a delay.','Recover trust with a precise status message.',['Acknowledge the missed update.','Name what is complete and unfinished.','Give a deadline and time zone.'])
add('toolkit','Choose a workflow','Can / cannot; deliverable requirements','tool-workflow','I need a square social post, and I want to edit the date later.','We can use an editor with separate text layers. A flattened generated image will not give you editable text.','Please include the editable file in the delivery.','We can use an editor with separate text layers.','We can keep the text editable.','I recommend assembling the post in an editor with separate text layers, so your team can update the date without regenerating the artwork.', [['editable text','Words the client can change independently.','The date must remain editable.'],['text layers','Separate editable text objects in a design file.','I will keep the date in a separate text layer.'],['flattened image','One pixel image without separate editable objects.','A flattened image is useful as a preview.']],'Why does the client need an editable source file?',['To change the date later.','To make the preview harder to open.','To add a random watermark.'],0,['Yes. The workflow follows the future editing requirement.','A preview can still be delivered in a common image format.','The client asks for editable text, not a watermark.'],['We can keep the text editable.','We can to keep the text editable.','We can keeping the text editable.'],0,'After “can”, use the base verb “keep”.','Your opening date may change. A colleague with basic editing skills will update the file.','Ask who will edit the file and what tool they use. Recommend a compatible editable source and a preview.','Choose tools from the deliverable, not from novelty.',['Ask about future editing.','Explain one tool capability.','Confirm source and preview formats.'])
add('toolkit','Explain a free-tier limit','Allowed use; practice vs paid work','tool-license','This free music generator sounds good. Can we use the track in our paid advert?','This free-plan track is for non-commercial use. We need a suitable commercial license before using it in a paid advert.','Let’s check the license and include any cost in the quote.','We need a suitable commercial license before using the track in a paid advert.','We need to check the license first.','Although the free track is useful for testing the mood, I would confirm a suitable commercial license before including music in the final advert.', [['for non-commercial use','For use outside paid or monetised work under the stated plan.','This example free-plan track is for non-commercial use.'],['before using','Put the check before the action.','Check the license before using the track.'],['include in the quote','Tell the client about a cost before they agree.','I will include that cost in the quote.']],'What can the designer do with the example free-plan track?',['Assume all free tracks are usable in paid ads.','Test the mood while checking a properly licensed final option.','Tell the client that no music ever needs a license.'],1,['Free price does not decide the usage rights.','Yes. Practice and final paid-client use may have different conditions.','The license still matters; the source or plan sets the conditions.'],['We need check the license.','We need to check the license.','We need checking the license.'],1,'Use “need to” followed by the base verb: need to check.','Your budget is small, but the final video will promote paid products. Ask whether there is a genuinely usable low-cost option.','Distinguish a free practice sample from a licensed final track. Offer a legal alternative without promising unverified rights.','Discuss the cost and permitted use of media.',['Explain the specific plan limit.','Ask or confirm the final use.','Include any license cost before agreement.'])
add('toolkit','Write a useful production brief','Requirements; negative constraints; aspect ratio','tool-prompt','The background needs to leave room for our headline.','I’ll ask for a landscape café image with empty space on the left and no generated text. Then I’ll add the approved wording in the editor.','Please keep the table and cup away from that empty area.','Leave empty space on the left for the headline.','Leave space on the left. Do not add text.','Create a landscape café background with clear negative space on the left, while keeping the cup and table outside the headline area.', [['leave space','Reserve an area for another element.','Leave space for the headline.'],['on the left','Identify a specific part of the frame.','The headline will go on the left.'],['approved wording','Text the client has confirmed.','I will add the approved wording myself.']],'Which task will the designer do in the editor?',['Invent the café’s final address.','Add the approved headline as editable text.','Accept whatever text the generator creates.'],1,['The address must come from the client.','Yes. The prompt separates the background asset from the final text.','The designer explicitly requests no generated text.'],['Leave space for the headline.','Leave space to the headline.','Leave space at the headline.'],0,'Use “space for” when explaining what the empty area will hold.','You need the headline on the left because the right side carries a cup image. You also need an empty area for a future offer.','Ask about placement and dimensions. Write a concise asset brief with both positive and negative requirements.','Produce a prompt another person could use without guessing.',['Name subject and format.','Specify the empty area.','Keep factual wording separate from generation.'])
add('visual','Separate observation from interpretation','I notice + fact; may suggest + inference','scene','Which lighting feels better for our café invitation?','I notice warmer light in A. It may suggest a more welcoming mood, but we should check whether that fits your audience.','Our daytime customers want a quiet place to read.','The warmer light may suggest a more welcoming mood.','A looks warmer. It feels welcoming to me.','The warmer cast may support a welcoming mood, although the audience’s response needs checking rather than assuming.', [['I notice','Introduce something you can point to.','I notice a warmer color cast.'],['may suggest','Offer a possible meaning, not a proven fact.','The shadow may suggest tension.'],['to me','Show that an interpretation is yours.','The softer light feels calmer to me.']],'Which sentence is an interpretation rather than a visible fact?',['A has a warmer color cast.','The same cup appears in both frames.','A may feel more welcoming.'],2,['The color cast can be compared visually.','The repeated cup is a visible detail.','Yes. A mood is a possible reading, not something the picture proves.'],['The light may suggest a calm mood.','The light may suggests a calm mood.','The light may to suggest a calm mood.'],0,'After “may”, use the base verb: may suggest.','Your café serves students in the day and busy groups in the evening. Ask which mood the proposed image is designed for.','Point to one visible lighting difference, offer a cautious interpretation, and ask about the actual audience.','Explain mood without claiming to know every viewer’s reaction.',['Separate what you see from what you infer.','Use may or to me for a reading.','Check the occasion and audience.'])
add('visual','Discuss a shape’s personality','Looks / feels; might + verb','shapes','Could we use the sharp triangle for our nursery mark?','We could, but the rounded shape might suggest a softer tone. Which personality should the nursery communicate?','Warm and reassuring, rather than exciting.','The rounded shape might suggest a softer tone.','The circle looks softer to me.','A rounded mark might support a softer tone, but I would compare it with the audience’s expectations before choosing a direction.', [['rounded shape','A shape with curved rather than sharp edges.','The mark uses a rounded shape.'],['might suggest','Offer a possibility while leaving room for another reading.','The triangle might suggest energy.'],['rather than','Contrast the preferred choice with an alternative.','We want reassurance rather than excitement.']],'Which personality does this client want?',['Warm and reassuring.','Aggressive and dangerous.','Whatever the designer personally likes.'],0,['Yes. The client names the desired tone.','That is not the tone the client requests.','The direction should serve this client’s audience.'],['The circle might suggests a softer tone.','The circle might suggest a softer tone.','The circle might suggesting a softer tone.'],1,'Use the base verb after “might”: might suggest.','Your nursery serves parents of young children. You want reassurance, but you do not want a childish or cartoonish mark.','Compare rounded and angular shapes. Ask about the audience and offer a tone without treating shape associations as universal.','Recommend a shape direction with a qualified reason.',['Describe the actual shape.','Qualify the interpretation.','Ask which brand personality matters.'])
add('visual','Ask for a cultural review','Could someone…; before final delivery','rtl','We need an Arabic version for our Gulf customers.','I’ll adapt the reading flow and alignment. Could someone on your team review the Arabic wording and layout before final delivery?','Yes. Keep our brand mark unchanged and send a preview first.','Could someone on your team review the Arabic wording and layout?','Could an Arabic reader check the words and layout?','Before final delivery, could a fluent Arabic reader review the wording, reading flow, and alignment while we keep the brand mark intact?', [['reading flow','The order and direction in which content is read.','The reading flow needs adapting.'],['keep unchanged','Do not alter this item.','Keep the brand mark unchanged.'],['review before delivery','Check the work before the final files are sent.','Please review the layout before delivery.']],'Which item should remain unchanged in this brief?',['The English text.','The whole layout direction.','The brand mark.'],2,['The text needs an Arabic version.','The reading flow and alignment need adaptation.','Yes. The client explicitly asks to keep the brand mark intact.'],['Could someone reviews the layout?','Could someone review the layout?','Could someone to review the layout?'],1,'After “could”, use the base verb: could someone review…?','You have an approved Arabic translation and a brand mark that must stay intact. Your colleague can review the proof.','Do not claim to validate Arabic if you cannot. Ask for approved wording and a local reviewer; confirm what will change.','Arrange an audience and language review.',['Ask for approved wording.','Confirm what stays intact.','Name the reviewer and review stage.'])
add('judgment','Report a factual error','Found + past; needs + noun / verb-ing','spelling','The draft looks good. Is it ready to publish?','I found a spelling error in “Opening”. I’ll correct the headline and check it against the approved copy before exporting.','Thanks. Please send the corrected proof first.','I found a spelling error in the headline.','The headline has a spelling mistake.','The draft is visually promising, but I found a spelling error that needs correcting before the final export.', [['I found','Report a problem you discovered.','I found a spelling error.'],['approved copy','The exact wording confirmed by the client.','Check the headline against the approved copy.'],['corrected proof','An updated preview for review.','I will send the corrected proof first.']],'What should happen before export?',['Correct the spelling and check the approved text.','Publish immediately because the colors look good.','Change the client’s actual offer without asking.'],0,['Yes. Accurate copy is part of the deliverable.','Visual quality does not cancel a factual error.','The client’s offer needs approval, not invention.'],['I found a spelling error.','I finded a spelling error.','I founded a spelling error.'],0,'The past of “find” is “found”. “Founded” means established an organisation.','You approved “Grand Opening” and want a corrected proof before it goes public.','Identify the specific error without blaming the tool, explain your correction, and ask for final approval.','Report a draft error and give a credible next step.',['Name the specific problem.','Use completed-review language.','Offer a correction and a proof.'])
add('judgment','Check against the brief','Meets / does not meet; needs to','format','This wide image looks good, but we asked for a square post.','The draft does not meet the required aspect ratio. I’ll rebuild it as a square and keep the text editable.','Please send the square preview and the editable source.','The draft does not meet the required aspect ratio.','The draft is wide. We need a square post.','Although the draft looks polished, it does not meet the square-format requirement or the need for an editable source.', [['meet the requirement','Satisfy something the brief asks for.','This version meets the requirement.'],['aspect ratio','The relationship between width and height.','The brief asks for a 1:1 aspect ratio.'],['editable source','The working file with elements that can be changed.','The client needs an editable source.']],'Why is the wide draft not ready?',['It is not new enough.','It does not meet the agreed format.','Every wide image is always bad design.'],1,['Novelty is not the requirement being checked.','Yes. The assessment is against this specific square-post brief.','Wide images suit other briefs; this brief requires a square.'],['The draft does not meets the brief.','The draft does not meeting the brief.','The draft does not meet the brief.'],2,'After “does not”, use the base verb: does not meet.','You need a 1:1 post and text your staff can edit. Both were in the agreed brief.','Compare the current draft with both requirements. Define the corrected preview and source deliverables.','Explain why a polished output can still fail a brief.',['Name the exact unmet requirement.','Propose a concrete fix.','Confirm the final file types.'])
